strong_ru_patch_code="\n# V20.7.18 — exact strongest Russian-capable model per connected provider.\n# Free-only policy remains in force: paid/unqualified providers stay disabled.\n_STRONG_RU_TARGET={\n    'groq':'openai/gpt-oss-120b',\n    'openrouter':'qwen/qwen3.8-27b:free',\n    'cloudflare':'@cf/openai/gpt-oss-120b',\n    'zai':'glm-4.7-flash',\n    'cerebras':'gpt-oss-120b',\n    'mistral':'mistral-large-latest',\n}\n_STRONG_RU_ACTIVE=('groq','cloudflare','zai','openrouter')\n_STRONG_RU_DISABLED={\n    'cerebras':'http_402_payment_required',\n    'mistral':'free_entitlement_unverified_or_rate_limited',\n}\n_STRONG_RU_CYR=re.compile(r'[А-Яа-яЁё]')\n\n# Canonical model environment: inherited code cannot silently select smaller models.\nGROQ_MODEL=_STRONG_RU_TARGET['groq']\nOPENROUTER_MODEL=_STRONG_RU_TARGET['openrouter']\ntry:\n    RESEARCH_MODEL=GROQ_MODEL\nexcept NameError:\n    pass\n\n_v20718_groq=groq_direct_chat\ndef groq_direct_chat(messages,model,max_tokens=3000,temperature=0.3):\n    return _v20718_groq(messages,_STRONG_RU_TARGET['groq'],\n                        min(2100,max(64,int(max_tokens))),temperature)\n\n_v20718_cloudflare=cloudflare_chat\ndef cloudflare_chat(messages,model,max_tokens=1800,temperature=0.3):\n    return _v20718_cloudflare(messages,_STRONG_RU_TARGET['cloudflare'],\n                              min(1800,max(64,int(max_tokens))),temperature)\n\n_v20718_openrouter=openrouter_specific_chat\ndef openrouter_specific_chat(messages,model,max_tokens=1800,temperature=0.3):\n    return _v20718_openrouter(messages,_STRONG_RU_TARGET['openrouter'],\n                              min(1800,max(64,int(max_tokens))),temperature)\n\n_v20718_call=_call_candidate\ndef _call_candidate(provider,model,messages,max_tokens,temperature):\n    if provider in _STRONG_RU_DISABLED:\n        raise RuntimeError('strong_provider_disabled:'+provider+':'+_STRONG_RU_DISABLED[provider])\n    expected=_STRONG_RU_TARGET.get(provider)\n    if expected is None:\n        raise RuntimeError('provider_not_in_strong_ru_policy:'+str(provider))\n    if str(model)!=expected:\n        raise RuntimeError('weaker_model_blocked:'+provider+':'+str(model))\n    return _v20718_call(provider,expected,messages,max_tokens,temperature)\n\n# Old paid Z.AI route is replaced only by the exact free Flash target.\ndef zai_chat(messages,max_tokens=1400,temperature=0.3):\n    return _call_candidate('zai',_STRONG_RU_TARGET['zai'],messages,\n                           min(1400,max(64,int(max_tokens))),temperature)\n\n# Mistral remains locally disabled until a no-charge entitlement is verified.\ndef mistral_chat(*args,**kwargs):\n    raise RuntimeError('mistral_strong_model_not_free_qualified')\n\ndef _adaptive_candidates(route):\n    out=[]\n    if GROQ_API_KEY:\n        out.append(('groq',_STRONG_RU_TARGET['groq']))\n    if CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN:\n        out.append(('cloudflare',_STRONG_RU_TARGET['cloudflare']))\n    if ZAI_API_KEY:\n        out.append(('zai',_STRONG_RU_TARGET['zai']))\n    if OPENROUTER_API_KEY:\n        out.append(('openrouter',_STRONG_RU_TARGET['openrouter']))\n    return out\n\n# Replace every inherited static route with the exact strongest-only table.\nfor _route in ('write','deep_research'):\n    MODEL_ROUTE_TABLE[_route]=_adaptive_candidates(_route)\n\ndef reserve_chat(messages,max_tokens=3000,temperature=0.35):\n    errors=[]\n    for provider,model in _adaptive_candidates('write'):\n        try:\n            out=_call_candidate(provider,model,messages,max_tokens,temperature)\n            if out and str(out).strip():\n                return out\n            errors.append(provider+':empty')\n        except Exception as err:\n            errors.append(provider+':'+cleanerr(err)[:150])\n    raise RuntimeError('no_strong_ru_provider: '+' | '.join(errors[-4:]))\n\nstate['strongest_ru_policy']='v20.7.18-exact-strongest-only'\nstate['strongest_ru_targets']=dict(_STRONG_RU_TARGET)\nstate['strongest_ru_disabled']=dict(_STRONG_RU_DISABLED)\nstate['model_route_table']={\n    r:[p+':'+m for p,m in _adaptive_candidates(r)]\n    for r in ('write','deep_research')\n}\nstate['strongest_ru_probe']={}\n\ndef _v20718_probe():\n    time.sleep(6)\n    msgs=[\n      {'role':'system','content':'Всегда отвечай на русском языке.'},\n      {'role':'user','content':'Ответь ровно одной короткой фразой: русский язык работает.'}\n    ]\n    for provider,model in _adaptive_candidates('write'):\n        try:\n            out=_call_candidate(provider,model,msgs,360,0.1)\n            txt=str(out or '').strip()\n            ok=bool(_STRONG_RU_CYR.search(txt))\n            state['strongest_ru_probe'][provider]={'ok':ok,'model':model}\n            marker='STRONG_RU_MODEL_OK' if ok else 'STRONG_RU_MODEL_FAILED'\n            payload={'provider':provider,'model':model}\n            if not ok: payload['reason']='no_cyrillic'\n            print(marker,json.dumps(payload,ensure_ascii=False),flush=True)\n        except Exception as err:\n            state['strongest_ru_probe'][provider]={\n              'ok':False,'model':model,'error':cleanerr(err)[:180]\n            }\n            print('STRONG_RU_MODEL_FAILED',json.dumps({\n              'provider':provider,'model':model,'error':cleanerr(err)[:180]\n            },ensure_ascii=False),flush=True)\n    print('ND_V20_7_18_STRONGEST_RU_POOL_READY',json.dumps({\n      'routes':state['model_route_table'],\n      'probe':state['strongest_ru_probe'],\n      'disabled':state['strongest_ru_disabled'],\n    },ensure_ascii=False),flush=True)\n\nthreading.Thread(target=_v20718_probe,daemon=True).start()\nprint('ND_V20_7_18_STRONGEST_RU_POLICY_READY',flush=True)\n"
